CREATE TABLE IF NOT EXISTS peppol_submission_events (
  id INTEGER PRIMARY KEY,
  submission_id INTEGER NOT NULL REFERENCES peppol_submissions(id),
  event_type TEXT NOT NULL CHECK(event_type IN ('delivery_reserved','delivery_failed','queued','status_observed','delivered')),
  document_id TEXT,
  status TEXT,
  observed_at TEXT NOT NULL,
  message TEXT NOT NULL DEFAULT '',
  public_url TEXT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_peppol_submission_events_submission
  ON peppol_submission_events(submission_id, id DESC);
CREATE TRIGGER IF NOT EXISTS peppol_submission_events_no_update
BEFORE UPDATE ON peppol_submission_events
BEGIN
  SELECT RAISE(ABORT, 'peppol submission events are append-only');
END;
CREATE TRIGGER IF NOT EXISTS peppol_submission_events_no_delete
BEFORE DELETE ON peppol_submission_events
BEGIN
  SELECT RAISE(ABORT, 'peppol submission events are append-only');
END;
